-- BuildPropertiesBeamNative  -  property-panel section for BeamNative (directAccess plain Beam).

local W = require(script.Parent.Widgets)
local BuildPropertiesBeamNative = {}

-- Build the BeamNative section into the Properties scroll frame. Hidden by default;
-- SelectionHandler reveals when BeamNative items are selected.
function BuildPropertiesBeamNative.buildSection(scroll, refs, order)
	local beamNativeDefs = {
		{name = "Emission", rows = {
			{key="Enabled", label="Enabled", type="toggle"},
		}},
		{name = "Shape", rows = {
			{key="Attachment0", label="Attachment 0", type="path", config={kind="instance-picker", directProperty="Attachment0", validate="Attachment"}},
			{key="Attachment1", label="Attachment 1", type="path", config={kind="instance-picker", directProperty="Attachment1", validate="Attachment"}},
			{key="Width0", label="Width 0", type="input", default="1"},
			{key="Width1", label="Width 1", type="input", default="1"},
			{key="CurveSize0", label="CurveSize 0", type="input", default="0"},
			{key="CurveSize1", label="CurveSize 1", type="input", default="0"},
			{key="Segments", label="Segments", type="input", default="10"},
			{key="FaceCamera", label="FaceCamera", type="toggle"},
			{key="ZOffset", label="ZOffset", type="input", default="0"},
		}},
		{name = "Appearance", rows = {
			{key="Color", label="Color", type="color"},
			{key="Brightness", label="Brightness", type="input", default="1"},
			{key="Transparency", label="Transparency", type="graph"},
			{key="LightEmission", label="Light Emission", type="input", default="0"},
			{key="LightInfluence", label="Light Influence", type="input", default="0"},
		}},
		{name = "Texture", rows = {
			{key="Texture", label="Texture", type="input", default="", placeholder="rbxassetid:// or ID"},
			{key="TextureLength", label="Tex. Length", type="input", default="1"},
			{key="TextureSpeed", label="Tex. Speed", type="input", default="1"},
			{key="TextureMode", label="Tex. Mode", type="dropdown", options={"Stretch","Wrap","Static"}, default="Stretch"},
		}},
		{name = "Advanced", collapsed = true, rows = {
			{key="PreloadTexture", label="Preload Texture", type="toggle"},
		}},
	}
	refs.BeamNativeSection, refs.BeamNative = W.buildTypeSection(scroll, "BeamNatives", beamNativeDefs, order or 3)
	refs.BeamNativeSection.Visible = false
end

return BuildPropertiesBeamNative

-- BuildPropertiesContainer  -  property-panel section for the Container type.
-- Same pattern as BuildPropertiesRocks. Consumer: BuildProperties.buildProperties()
-- calls buildSection(scroll, refs) during its build.

local W = require(script.Parent.Widgets)
local BuildPropertiesContainer = {}

function BuildPropertiesContainer.buildSection(scroll, refs)
	-- A row with one of these gets an asterisk that opens "Apply to": the kinds of thing the
	-- property acts on, of TypeDataContainer.APPLY_KINDS (PropertyInputsContainer wires it).
	-- Each row lists the kinds it means something to: only what is spawned has a spread, and a
	-- mesh has neither light property.
	-- A carried Force and the Reactors it reaches take the Container's time and nothing else.
	local applyTo = { kind = "apply-to", kinds = { "Emitter", "Mesh", "Beam", "Trail" } }
	local applyToTimed = { kind = "apply-to", kinds = { "Emitter", "Mesh", "Beam", "Trail", "Reactor" } }
	local applyToSpawned = { kind = "apply-to", kinds = { "Emitter", "Mesh" } }
	local applyToLit = { kind = "apply-to", kinds = { "Emitter", "Beam", "Trail" } }
	local containerDefs = {
		{name = "Emission", rows = {
			{key="Enabled",  label="Enabled", type="toggle"},
			{key="EmitMode", label="Type", type="dropdown", options={"Auto","Burst"}, default="Auto"},
			{key="Rate",     label="Rate", type="input", default="2"},
			{key="Lifetime", label="Lifetime", type="input", default="1, 1", placeholder="min, max"},
			-- The options are TypeDataContainer.MODES: the runtime compares the stored text.
			{key="Mode",     label="Mode", type="dropdown", options={"Absolute","Relative","Relative Lifetime","Relative Span"}, default="Absolute"},
		}},
		-- "x" rows multiply each emitter's own value (1 leaves it alone), "+" rows add to it (0 leaves it alone).
		-- Spread is one row for both axes (keys DriveSpreadX / DriveSpreadY), edited like a mesh's Size.
		-- Color drives the emitters' Color by Color Mode (TypeDataContainer.COLOR_MODES); white leaves it alone.
		{name = "Drive", rows = {
			{key="DriveRate",           label="Rate x", type="graph", config=applyTo},
			{key="DriveScale",          label="Scale x", type="graph", config=applyTo},
			{key="DriveTimescale",      label="Timescale x", type="graph", config=applyToTimed},
			{key="DriveBrightness",     label="Brightness x", type="graph", config=applyTo},
			{key="DriveSpread",         label="Spread +deg", type="axis_graph_select", axes={"X","Y"}, config=applyToSpawned},
			{key="DriveLightInfluence", label="Light Infl. +", type="graph", config=applyToLit},
			{key="DriveLightEmission",  label="Light Emis. +", type="graph", config=applyToLit},
			{key="DriveColor",          label="Color", type="color", config=applyTo},
			{key="ColorMode",           label="Color Mode", type="dropdown", options={"Recolor","Colorize","Shift","Tint"}, default="Recolor"},
		}},
		{name = "Advanced", collapsed = true, rows = {
			{key="EmitParent", label="Emit Into", type="path", config={kind="instance-picker", objectValue="EmitParent", acceptAnyInstance=true}},
		}},
	}
	refs.ContainerSection, refs.Container = W.buildTypeSection(scroll, "Containers", containerDefs, 3)
	refs.ContainerSection.Visible = false
end

return BuildPropertiesContainer
